"""Project discussions, object comments, follows and notifications (P34-2/3/7, D37 ⑤).

- Threads carry no audience of their own: SELECT re-evaluates the subject (project, task,
  document) under the reader's own RLS, so narrowing the object narrows its comments.
- Only a named human acting for themself posts, edits or retracts; the agent role has no
  privilege on any of these tables. Retraction keeps every version (P34-2).
- Notifications, follows and the fan-out to followers are written only by the SECURITY
  DEFINER functions below, which drop the operator, re-check the recipient's access,
  apply mute and level, and merge repeats within the window (P41-9: 10 minutes).

Written as placeholder s0_0874; s0_0869 since the 11-09 integration.
"""

# ruff: noqa: E501 -- Reviewed applied SQL literals remain byte-identical.

TABLES = ('discussion_threads', 'discussion_messages', 'discussion_message_versions', 'discussion_follows', 'notifications', 'notification_preferences')

# Filled from the exact reviewed ORM tables (discussions.models, notifications.models).
TABLE_SQL = ("\nCREATE TABLE discussion_threads (\n\tcategory_id UUID NOT NULL, \n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tsubject_type VARCHAR(16) NOT NULL, \n\tsubject_id UUID NOT NULL, \n\ttitle VARCHAR(160), \n\tauthor_id UUID NOT NULL, \n\trequest_key UUID NOT NULL, \n\trequest_sha256 VARCHAR(64) NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, id), \n\tUNIQUE (tenant_id, author_id, request_key), \n\tCONSTRAINT discussion_thread_product_fk FOREIGN KEY(tenant_id, category_id, product_id) REFERENCES products (tenant_id, category_id, id), \n\tCONSTRAINT discussion_thread_project_fk FOREIGN KEY(tenant_id, product_id, project_id) REFERENCES projects (tenant_id, product_id, id), \n\tCONSTRAINT discussion_thread_author_fk FOREIGN KEY(tenant_id, author_id) REFERENCES principals (tenant_id, id), \n\tCONSTRAINT discussion_thread_shape CHECK (subject_type IN ('project','work_task','artifact') AND ((subject_type='project') = (title IS NOT NULL)) AND (subject_type<>'project' OR subject_id=project_id) AND (title IS NULL OR char_length(btrim(title)) BETWEEN 1 AND 160) AND request_sha256 ~ '^[a-f0-9]{64}$')\n)\n\n", 'CREATE INDEX ix_discussion_threads_category_id ON discussion_threads (category_id)', 'CREATE INDEX ix_discussion_threads_project ON discussion_threads (tenant_id, project_id, created_at)', 'CREATE INDEX ix_discussion_threads_tenant_id ON discussion_threads (tenant_id)', "CREATE UNIQUE INDEX uq_discussion_object_thread ON discussion_threads (tenant_id, project_id, subject_type, subject_id) WHERE subject_type<>'project'", "\nCREATE TABLE discussion_messages (\n\tthread_id UUID NOT NULL, \n\tsequence INTEGER NOT NULL, \n\tauthor_id UUID NOT NULL, \n\trevision INTEGER NOT NULL, \n\tstate VARCHAR(16) NOT NULL, \n\tbody TEXT NOT NULL, \n\tmentions JSONB NOT NULL, \n\tsubject_revision INTEGER, \n\tupdated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tchange_seq BIGINT NOT NULL, \n\trequest_key UUID NOT NULL, \n\trequest_sha256 VARCHAR(64) NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, id), \n\tUNIQUE (tenant_id, thread_id, sequence), \n\tUNIQUE (tenant_id, author_id, request_key), \n\tCONSTRAINT discussion_message_thread_fk FOREIGN KEY(tenant_id, thread_id) REFERENCES discussion_threads (tenant_id, id), \n\tCONSTRAINT discussion_message_author_fk FOREIGN KEY(tenant_id, author_id) REFERENCES principals (tenant_id, id), \n\tCONSTRAINT discussion_message_shape CHECK (sequence>0 AND revision>0 AND state IN ('posted','edited','retracted') AND jsonb_typeof(mentions)='array' AND ((state='retracted' AND body='' AND mentions='[]'::jsonb) OR (state<>'retracted' AND char_length(btrim(body)) BETWEEN 1 AND 8000)) AND (subject_revision IS NULL OR subject_revision>0) AND request_sha256 ~ '^[a-f0-9]{64}$')\n)\n\n", 'CREATE INDEX ix_discussion_messages_tenant_id ON discussion_messages (tenant_id)', 'CREATE INDEX ix_discussion_messages_thread_change ON discussion_messages (tenant_id, thread_id, change_seq)', "\nCREATE TABLE discussion_message_versions (\n\tmessage_id UUID NOT NULL, \n\tthread_id UUID NOT NULL, \n\trevision INTEGER NOT NULL, \n\tstate VARCHAR(16) NOT NULL, \n\tbody TEXT NOT NULL, \n\tmentions JSONB NOT NULL, \n\tsubject_revision INTEGER, \n\teditor_id UUID NOT NULL, \n\trequest_key UUID NOT NULL, \n\trequest_sha256 VARCHAR(64) NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, id), \n\tUNIQUE (tenant_id, message_id, revision), \n\tUNIQUE (tenant_id, editor_id, request_key), \n\tCONSTRAINT discussion_version_message_fk FOREIGN KEY(tenant_id, message_id) REFERENCES discussion_messages (tenant_id, id), \n\tCONSTRAINT discussion_version_thread_fk FOREIGN KEY(tenant_id, thread_id) REFERENCES discussion_threads (tenant_id, id), \n\tCONSTRAINT discussion_version_editor_fk FOREIGN KEY(tenant_id, editor_id) REFERENCES principals (tenant_id, id), \n\tCONSTRAINT discussion_version_shape CHECK (revision>0 AND state IN ('posted','edited','retracted') AND jsonb_typeof(mentions)='array' AND (state='retracted' OR char_length(btrim(body)) BETWEEN 1 AND 8000) AND request_sha256 ~ '^[a-f0-9]{64}$')\n)\n\n", 'CREATE INDEX ix_discussion_message_versions_tenant_id ON discussion_message_versions (tenant_id)', "\nCREATE TABLE discussion_follows (\n\tprincipal_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\ttarget_kind VARCHAR(16) NOT NULL, \n\ttarget_id UUID NOT NULL, \n\tfollowed BOOLEAN NOT NULL, \n\treason VARCHAR(16) NOT NULL, \n\tupdated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, id), \n\tUNIQUE (tenant_id, principal_id, target_kind, target_id), \n\tCONSTRAINT discussion_follow_principal_fk FOREIGN KEY(tenant_id, principal_id) REFERENCES principals (tenant_id, id), \n\tCONSTRAINT discussion_follow_project_fk FOREIGN KEY(project_id) REFERENCES projects (id), \n\tCONSTRAINT discussion_follow_shape CHECK (target_kind IN ('thread','work_task') AND reason IN ('created','commented','mentioned','assigned','manual'))\n)\n\n", 'CREATE INDEX ix_discussion_follows_target ON discussion_follows (tenant_id, target_kind, target_id)', 'CREATE INDEX ix_discussion_follows_tenant_id ON discussion_follows (tenant_id)', "\nCREATE TABLE notifications (\n\trecipient_id UUID NOT NULL, \n\tcategory_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tcategory VARCHAR(16) NOT NULL, \n\treason VARCHAR(40) NOT NULL, \n\tsubject_kind VARCHAR(16) NOT NULL, \n\tsubject_id UUID NOT NULL, \n\tthread_id UUID, \n\tmerge_key VARCHAR(240) NOT NULL, \n\tactor_ids UUID[] NOT NULL, \n\tevent_count INTEGER NOT NULL, \n\tfirst_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tlast_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tlatest JSONB NOT NULL, \n\tdelivery VARCHAR(16) NOT NULL, \n\tread_at TIMESTAMP WITH TIME ZONE, \n\tsnoozed_until TIMESTAMP WITH TIME ZONE, \n\tarchived_at TIMESTAMP WITH TIME ZONE, \n\tchange_seq BIGINT NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, id), \n\tCONSTRAINT notification_recipient_fk FOREIGN KEY(tenant_id, recipient_id) REFERENCES principals (tenant_id, id), \n\tCONSTRAINT notification_category_fk FOREIGN KEY(tenant_id, category_id) REFERENCES categories (tenant_id, id), \n\tCONSTRAINT notification_project_fk FOREIGN KEY(project_id) REFERENCES projects (id), \n\tCONSTRAINT notification_shape CHECK (category IN ('mention','assigned','decide','agent','follow') AND subject_kind IN ('thread','work_task','project','member_handover') AND delivery IN ('instant','digest') AND event_count>0 AND cardinality(actor_ids) BETWEEN 0 AND 20 AND last_at>=first_at AND jsonb_typeof(latest)='object' AND (delivery='instant' OR category='follow'))\n)\n\n", 'CREATE INDEX ix_notifications_category_id ON notifications (category_id)', 'CREATE INDEX ix_notifications_open_merge ON notifications (tenant_id, recipient_id, merge_key) WHERE read_at IS NULL AND archived_at IS NULL', 'CREATE INDEX ix_notifications_recipient_change ON notifications (tenant_id, recipient_id, change_seq)', 'CREATE INDEX ix_notifications_tenant_id ON notifications (tenant_id)', "\nCREATE TABLE notification_preferences (\n\tprincipal_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tlevel VARCHAR(16) NOT NULL, \n\tmuted BOOLEAN NOT NULL, \n\tdigest BOOLEAN NOT NULL, \n\trevision INTEGER NOT NULL, \n\tupdated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, id), \n\tUNIQUE (tenant_id, principal_id, project_id), \n\tCONSTRAINT notification_preference_principal_fk FOREIGN KEY(tenant_id, principal_id) REFERENCES principals (tenant_id, id), \n\tCONSTRAINT notification_preference_project_fk FOREIGN KEY(project_id) REFERENCES projects (id), \n\tCONSTRAINT notification_preference_shape CHECK (level IN ('all','important','mentions') AND revision>0)\n)\n\n", 'CREATE INDEX ix_notification_preferences_tenant_id ON notification_preferences (tenant_id)')

SEQUENCE_SQL = (
    'CREATE SEQUENCE public.discussion_change_seq',
    'CREATE SEQUENCE public.notification_change_seq',
    'REVOKE ALL ON SEQUENCE public.discussion_change_seq, public.notification_change_seq FROM PUBLIC,pdos_next_app,pdos_agent,pdos_next_auth,pdos_next_dispatch',
)

FUNCTIONS = (
    ('discussion_project_open(uuid,uuid)', "CREATE FUNCTION public.discussion_project_open(t uuid, project uuid) RETURNS boolean\n LANGUAGE sql STABLE SET search_path=pg_catalog,public,pg_temp AS $$\n SELECT EXISTS(SELECT 1 FROM public.projects p WHERE p.tenant_id=t AND p.id=project\n  AND (p.visibility='category' OR p.owner_id=public.scope_requester() OR EXISTS(\n   SELECT 1 FROM public.object_audiences a WHERE a.tenant_id=p.tenant_id AND a.category_id=p.category_id\n    AND a.object_type='projects' AND a.subject_id=p.id AND a.owner_id=p.owner_id\n    AND a.principal_id=public.scope_requester())))\n$$", ('pdos_next_app',)),
    ('discussion_subject_open(uuid,uuid,uuid,uuid,text,uuid)', "CREATE FUNCTION public.discussion_subject_open(t uuid, c uuid, product uuid, project uuid, subject_type text, subject uuid) RETURNS boolean\n LANGUAGE sql STABLE SET search_path=pg_catalog,public,pg_temp AS $$\n SELECT CASE subject_type\n  WHEN 'project' THEN public.discussion_project_open(t, project)\n  WHEN 'work_task' THEN EXISTS(SELECT 1 FROM public.work_task_currents x WHERE x.tenant_id=t AND x.category_id=c\n    AND x.product_id=product AND x.project_id=project AND x.task_id=subject)\n   AND (public.discussion_project_open(t, project) OR public.project_handover_subject(t, project, 'work_task', subject))\n  WHEN 'artifact' THEN public.discussion_project_open(t, project) AND EXISTS(SELECT 1 FROM public.artifact_versions a\n    WHERE a.tenant_id=t AND a.category_id=c AND a.id=subject AND a.status='active'\n     AND (a.product_id IS NULL OR a.product_id=product))\n  ELSE false END\n$$", ('pdos_next_app',)),
    ('discussion_person_open(uuid,uuid,uuid,uuid,text,uuid,uuid)', "CREATE FUNCTION public.discussion_person_open(t uuid, c uuid, product uuid, project uuid, subject_type text, subject uuid, person uuid) RETURNS boolean\n LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\n SELECT EXISTS(SELECT 1 FROM principals x WHERE x.tenant_id=t AND x.id=person AND x.active AND x.kind='human')\n  AND EXISTS(SELECT 1 FROM grants g WHERE g.tenant_id=t AND g.category_id=c AND g.principal_id=person\n   AND (g.expires_at IS NULL OR g.expires_at>statement_timestamp()))\n  AND EXISTS(SELECT 1 FROM products m WHERE m.tenant_id=t AND m.category_id=c AND m.id=product\n   AND (m.visibility='category' OR m.owner_id=person OR EXISTS(SELECT 1 FROM object_audiences a\n    WHERE a.tenant_id=t AND a.category_id=c AND a.object_type='products' AND a.subject_id=m.id\n     AND a.owner_id=m.owner_id AND a.principal_id=person)))\n  AND CASE subject_type\n   WHEN 'project' THEN project_person_open(t, project, person)\n   WHEN 'work_task' THEN EXISTS(SELECT 1 FROM work_task_currents x WHERE x.tenant_id=t AND x.category_id=c\n     AND x.product_id=product AND x.project_id=project AND x.task_id=subject)\n    AND (project_person_open(t, project, person) OR (project_handover_only(t, project, person)\n     AND EXISTS(SELECT 1 FROM project_handover_items_of(t, project, person) i\n      WHERE i.kind IN ('work_task','work_commitment') AND i.task_id=subject)))\n   WHEN 'artifact' THEN project_person_open(t, project, person) AND EXISTS(SELECT 1 FROM artifact_versions a\n     WHERE a.tenant_id=t AND a.category_id=c AND a.id=subject AND a.status='active'\n      AND (a.product_id IS NULL OR a.product_id=product)\n      AND (a.visibility='category' OR a.owner_id=person OR EXISTS(SELECT 1 FROM object_audiences o\n       WHERE o.tenant_id=t AND o.category_id=c AND o.object_type='artifact_versions' AND o.subject_id=a.id\n        AND o.owner_id=a.owner_id AND o.principal_id=person))\n      AND (a.original_id IS NULL OR EXISTS(SELECT 1 FROM uploaded_originals u WHERE u.tenant_id=t\n       AND u.category_id=c AND u.id=a.original_id AND (u.visibility='category' OR u.owner_id=person\n        OR EXISTS(SELECT 1 FROM object_audiences o WHERE o.tenant_id=t AND o.category_id=c\n         AND o.object_type='uploaded_originals' AND o.subject_id=u.id AND o.owner_id=u.owner_id\n         AND o.principal_id=person)))))\n   ELSE false END\n$$", ('pdos_next_app',)),
    ('discussion_subject_revision(uuid,uuid)', "CREATE FUNCTION public.discussion_subject_revision(t uuid, thread uuid) RETURNS integer\n LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\n SELECT CASE th.subject_type\n  WHEN 'work_task' THEN (SELECT x.revision FROM work_task_currents x WHERE x.tenant_id=t\n   AND x.product_id=th.product_id AND x.task_id=th.subject_id)\n  WHEN 'artifact' THEN (SELECT a.revision FROM artifact_versions a WHERE a.tenant_id=t AND a.id=th.subject_id)\n  ELSE NULL END\n FROM discussion_threads th WHERE th.tenant_id=t AND th.id=thread\n$$", ()),
    ('discussion_thread_append_only()', "CREATE FUNCTION public.discussion_thread_append_only() RETURNS trigger\n LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$ BEGIN\n RAISE EXCEPTION 'Discussion history is append only' USING ERRCODE='23514'; END $$", ()),
    ('guard_discussion_message()', "CREATE FUNCTION public.guard_discussion_message() RETURNS trigger\n LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\nDECLARE latest integer;\nBEGIN\n IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Discussion messages are retracted, never deleted' USING ERRCODE='23514'; END IF;\n IF TG_OP='INSERT' THEN\n  PERFORM pg_advisory_xact_lock(hashtextextended('discussion-thread:'||NEW.thread_id::text,0));\n  SELECT coalesce(max(sequence),0) INTO latest FROM discussion_messages WHERE tenant_id=NEW.tenant_id AND thread_id=NEW.thread_id;\n  IF NEW.sequence<>latest+1 OR NEW.revision<>1 OR NEW.state<>'posted' OR NEW.author_id IS DISTINCT FROM scope_actor()\n   OR NEW.author_id IS DISTINCT FROM scope_requester()\n   OR NEW.subject_revision IS DISTINCT FROM discussion_subject_revision(NEW.tenant_id, NEW.thread_id) THEN\n   RAISE EXCEPTION 'Invalid discussion message' USING ERRCODE='23514'; END IF;\n ELSE\n  IF ROW(NEW.id,NEW.tenant_id,NEW.created_at,NEW.thread_id,NEW.sequence,NEW.author_id,NEW.request_key,NEW.request_sha256)\n    IS DISTINCT FROM ROW(OLD.id,OLD.tenant_id,OLD.created_at,OLD.thread_id,OLD.sequence,OLD.author_id,OLD.request_key,OLD.request_sha256)\n   OR OLD.state='retracted' OR NEW.state NOT IN ('edited','retracted') OR NEW.revision<>OLD.revision+1\n   OR OLD.author_id IS DISTINCT FROM scope_actor() OR scope_actor() IS DISTINCT FROM scope_requester()\n   OR (NEW.state='edited' AND NEW.subject_revision IS DISTINCT FROM discussion_subject_revision(NEW.tenant_id, NEW.thread_id))\n   OR (NEW.state='retracted' AND NEW.subject_revision IS DISTINCT FROM OLD.subject_revision) THEN\n   RAISE EXCEPTION 'Only the author edits or retracts a message' USING ERRCODE='23514'; END IF;\n END IF;\n NEW.updated_at=statement_timestamp();\n NEW.change_seq=nextval('public.discussion_change_seq');\n RETURN NEW;\nEND $$", ()),
    ('require_discussion_version()', "CREATE FUNCTION public.require_discussion_version() RETURNS trigger\n LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\nDECLARE m discussion_messages;\nBEGIN\n SELECT * INTO m FROM discussion_messages WHERE tenant_id=NEW.tenant_id AND id=NEW.id;\n IF NOT EXISTS(SELECT 1 FROM discussion_message_versions v WHERE v.tenant_id=m.tenant_id AND v.message_id=m.id\n   AND v.revision=m.revision AND v.thread_id=m.thread_id AND v.state=m.state AND v.editor_id=m.author_id\n   AND v.subject_revision IS NOT DISTINCT FROM m.subject_revision\n   AND (m.state='retracted' OR (v.body=m.body AND v.mentions=m.mentions))) THEN\n  RAISE EXCEPTION 'Discussion message lacks its version' USING ERRCODE='23514'; END IF;\n RETURN NULL;\nEND $$", ()),
    ('guard_notification()', "CREATE FUNCTION public.guard_notification() RETURNS trigger\n LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\nBEGIN\n IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Notifications are archived, never deleted' USING ERRCODE='23514'; END IF;\n IF TG_OP='UPDATE' AND (ROW(NEW.id,NEW.tenant_id,NEW.created_at,NEW.recipient_id,NEW.category_id,NEW.project_id,NEW.category,\n    NEW.subject_kind,NEW.subject_id,NEW.thread_id,NEW.merge_key,NEW.first_at,NEW.delivery)\n   IS DISTINCT FROM ROW(OLD.id,OLD.tenant_id,OLD.created_at,OLD.recipient_id,OLD.category_id,OLD.project_id,OLD.category,\n    OLD.subject_kind,OLD.subject_id,OLD.thread_id,OLD.merge_key,OLD.first_at,OLD.delivery)\n   OR NEW.event_count<OLD.event_count OR NEW.last_at<OLD.last_at) THEN\n  RAISE EXCEPTION 'Notification identity is immutable' USING ERRCODE='23514'; END IF;\n NEW.change_seq=nextval('public.notification_change_seq');\n RETURN NEW;\nEND $$", ()),
    ('guard_notification_preference()', "CREATE FUNCTION public.guard_notification_preference() RETURNS trigger\n LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\nBEGIN\n IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Notification settings are replaced, not deleted' USING ERRCODE='23514'; END IF;\n IF TG_OP='INSERT' AND NEW.revision<>1 THEN RAISE EXCEPTION 'Invalid notification setting' USING ERRCODE='23514'; END IF;\n IF TG_OP='UPDATE' AND (ROW(NEW.id,NEW.tenant_id,NEW.created_at,NEW.principal_id,NEW.project_id)\n   IS DISTINCT FROM ROW(OLD.id,OLD.tenant_id,OLD.created_at,OLD.principal_id,OLD.project_id) OR NEW.revision<>OLD.revision+1) THEN\n  RAISE EXCEPTION 'Invalid notification setting change' USING ERRCODE='23514'; END IF;\n NEW.updated_at=statement_timestamp();\n RETURN NEW;\nEND $$", ()),
    ('notification_subject_open(uuid,uuid,text,uuid,uuid)', "CREATE FUNCTION public.notification_subject_open(t uuid, person uuid, kind text, subject uuid, project uuid) RETURNS boolean\n LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\n SELECT CASE kind\n  WHEN 'thread' THEN EXISTS(SELECT 1 FROM discussion_threads th WHERE th.tenant_id=t AND th.id=subject AND th.project_id=project\n   AND discussion_person_open(t, th.category_id, th.product_id, th.project_id, th.subject_type, th.subject_id, person))\n  WHEN 'work_task' THEN EXISTS(SELECT 1 FROM work_task_currents x WHERE x.tenant_id=t AND x.task_id=subject AND x.project_id=project\n   AND discussion_person_open(t, x.category_id, x.product_id, x.project_id, 'work_task', x.task_id, person))\n  WHEN 'project' THEN subject=project AND EXISTS(SELECT 1 FROM projects p WHERE p.tenant_id=t AND p.id=project\n   AND discussion_person_open(t, p.category_id, p.product_id, p.id, 'project', p.id, person))\n  WHEN 'member_handover' THEN EXISTS(SELECT 1 FROM projects p WHERE p.tenant_id=t AND p.id=project AND p.owner_id=person\n   AND discussion_person_open(t, p.category_id, p.product_id, p.id, 'project', p.id, person))\n  ELSE false END\n$$", ('pdos_next_app',)),
    ('notification_emit(uuid,uuid,text,text,boolean,uuid,text,uuid,uuid,jsonb,integer)', 'CREATE FUNCTION public.notification_emit(t uuid, p_recipient uuid, p_category text, p_reason text, p_important boolean,\n  p_project uuid, p_kind text, p_subject uuid, p_thread uuid, p_latest jsonb, p_window integer) RETURNS uuid\n LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\nDECLARE writer principals; pref notification_preferences; proj projects; prior notifications; mode text := \'instant\'; mkey text; created uuid;\nBEGIN\n IF t IS DISTINCT FROM nullif(current_setting(\'pdos.tenant_id\',true),\'\')::uuid OR p_window NOT BETWEEN 60 AND 86400\n  OR p_category NOT IN (\'mention\',\'assigned\',\'decide\',\'agent\',\'follow\') OR jsonb_typeof(p_latest)<>\'object\' THEN\n  RAISE EXCEPTION \'Invalid notification event\' USING ERRCODE=\'23514\'; END IF;\n SELECT * INTO writer FROM principals WHERE tenant_id=t AND id=scope_actor() AND active;\n IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM principals x WHERE x.tenant_id=t AND x.id=scope_requester() AND x.active) THEN\n  RAISE EXCEPTION \'Notification needs an active writer\' USING ERRCODE=\'23514\'; END IF;\n -- The operator never receives a notification about their own action (§8).\n IF p_recipient=scope_actor() OR p_recipient=scope_requester() THEN RETURN NULL; END IF;\n -- 小Pai\'s own successful writes notify nobody except the assignee of a task (DC-11 §5, P53).\n IF writer.kind<>\'human\' AND p_category<>\'assigned\' THEN RETURN NULL; END IF;\n -- The writer must see the subject too, and the recipient must see it now.\n IF NOT (notification_subject_open(t, scope_requester(), p_kind, p_subject, p_project)\n   OR (p_kind=\'member_handover\' AND EXISTS(SELECT 1 FROM tenant_administrators a WHERE a.tenant_id=t\n    AND a.principal_id=scope_actor() AND a.active)))\n  OR NOT notification_subject_open(t, p_recipient, p_kind, p_subject, p_project) THEN RETURN NULL; END IF;\n SELECT * INTO STRICT proj FROM projects WHERE tenant_id=t AND id=p_project;\n SELECT * INTO pref FROM notification_preferences WHERE tenant_id=t AND principal_id=p_recipient AND project_id=p_project;\n IF FOUND AND p_category=\'follow\' THEN\n  -- Mute and the level filter only "关注的变化"; mentions, assignments and decisions still arrive.\n  IF pref.muted OR pref.level=\'mentions\' OR (pref.level=\'important\' AND NOT p_important) THEN RETURN NULL; END IF;\n  IF pref.digest THEN mode=\'digest\'; END IF;\n END IF;\n mkey := p_category||\':\'||p_kind||\':\'||p_subject::text||\':\'||coalesce(p_thread::text,\'-\');\n PERFORM pg_advisory_xact_lock(hashtextextended(\'notification:\'||t::text||\':\'||p_recipient::text||\':\'||mkey,0));\n SELECT * INTO prior FROM notifications n WHERE n.tenant_id=t AND n.recipient_id=p_recipient AND n.merge_key=mkey\n  AND n.read_at IS NULL AND n.archived_at IS NULL AND n.snoozed_until IS NULL AND n.delivery=mode\n  AND n.last_at>=statement_timestamp()-make_interval(secs=>p_window)\n  ORDER BY n.last_at DESC LIMIT 1 FOR UPDATE;\n IF FOUND THEN\n  UPDATE notifications SET event_count=event_count+1, last_at=statement_timestamp(), reason=p_reason, latest=p_latest,\n   actor_ids=CASE WHEN scope_actor()=ANY(actor_ids) OR cardinality(actor_ids)>=20 THEN actor_ids ELSE actor_ids||scope_actor() END\n  WHERE id=prior.id;\n  RETURN prior.id;\n END IF;\n INSERT INTO notifications(id, tenant_id, created_at, recipient_id, category_id, project_id, category, reason, subject_kind,\n   subject_id, thread_id, merge_key, actor_ids, event_count, first_at, last_at, latest, delivery, change_seq)\n VALUES (gen_random_uuid(), t, statement_timestamp(), p_recipient, proj.category_id, p_project, p_category, p_reason, p_kind,\n   p_subject, p_thread, mkey, ARRAY[scope_actor()], 1, statement_timestamp(), statement_timestamp(), p_latest, mode, 0)\n RETURNING id INTO created;\n RETURN created;\nEND $$', ('pdos_next_app',)),
    ('notification_emit_followers(uuid,text[],uuid[],text,text,boolean,uuid,text,uuid,uuid,jsonb,integer,uuid[])', "CREATE FUNCTION public.notification_emit_followers(t uuid, p_target_kinds text[], p_targets uuid[], p_category text, p_reason text,\n  p_important boolean, p_project uuid, p_kind text, p_subject uuid, p_thread uuid, p_latest jsonb, p_window integer, p_exclude uuid[]) RETURNS integer\n LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\nDECLARE person uuid; sent integer := 0;\nBEGIN\n IF t IS DISTINCT FROM nullif(current_setting('pdos.tenant_id',true),'')::uuid\n  OR cardinality(p_target_kinds) IS DISTINCT FROM cardinality(p_targets) OR cardinality(p_targets) NOT BETWEEN 1 AND 4\n  OR NOT notification_subject_open(t, scope_requester(), p_kind, p_subject, p_project) THEN\n  RAISE EXCEPTION 'Follower fan-out needs a visible subject' USING ERRCODE='23514'; END IF;\n -- Each follower once, however many of the targets they follow (thread and its task).\n FOR person IN SELECT DISTINCT x.principal_id FROM discussion_follows x\n   JOIN unnest(p_target_kinds, p_targets) AS g(kind, target) ON g.kind=x.target_kind AND g.target=x.target_id\n   WHERE x.tenant_id=t AND x.followed AND NOT x.principal_id=ANY(coalesce(p_exclude, ARRAY[]::uuid[]))\n   ORDER BY x.principal_id LOOP\n  IF notification_emit(t, person, p_category, p_reason, p_important, p_project, p_kind, p_subject, p_thread, p_latest, p_window) IS NOT NULL THEN\n   sent := sent + 1; END IF;\n END LOOP;\n RETURN sent;\nEND $$", ('pdos_next_app',)),
    ('discussion_follow_set(uuid,uuid,text,uuid,uuid,text,boolean)', "CREATE FUNCTION public.discussion_follow_set(t uuid, p_person uuid, p_kind text, p_target uuid, p_project uuid,\n  p_reason text, p_explicit boolean) RETURNS boolean\n LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\nDECLARE subject_kind text := CASE p_kind WHEN 'thread' THEN 'thread' WHEN 'work_task' THEN 'work_task' END;\nBEGIN\n IF t IS DISTINCT FROM nullif(current_setting('pdos.tenant_id',true),'')::uuid OR subject_kind IS NULL\n  OR NOT EXISTS(SELECT 1 FROM principals x WHERE x.tenant_id=t AND x.id=scope_actor() AND x.active)\n  OR NOT notification_subject_open(t, scope_requester(), subject_kind, p_target, p_project) THEN\n  RAISE EXCEPTION 'Follow needs a visible subject' USING ERRCODE='23514'; END IF;\n IF p_explicit THEN\n  -- An explicit choice is the person's own (§8 可以取消关注).\n  IF p_person IS DISTINCT FROM scope_requester() OR scope_actor() IS DISTINCT FROM scope_requester()\n   OR p_reason NOT IN ('follow','unfollow') THEN\n   RAISE EXCEPTION 'Only the person changes their own follow' USING ERRCODE='23514'; END IF;\n  INSERT INTO discussion_follows(id, tenant_id, created_at, principal_id, project_id, target_kind, target_id, followed, reason, updated_at)\n  VALUES (gen_random_uuid(), t, statement_timestamp(), p_person, p_project, p_kind, p_target, p_reason='follow', 'manual', statement_timestamp())\n  ON CONFLICT (tenant_id, principal_id, target_kind, target_id)\n  DO UPDATE SET followed=(p_reason='follow'), reason='manual', updated_at=statement_timestamp();\n  RETURN true;\n END IF;\n -- Automatic follow (created, commented, mentioned, assigned) never overrides a choice.\n IF p_reason NOT IN ('created','commented','mentioned','assigned')\n  OR NOT notification_subject_open(t, p_person, subject_kind, p_target, p_project) THEN RETURN false; END IF;\n INSERT INTO discussion_follows(id, tenant_id, created_at, principal_id, project_id, target_kind, target_id, followed, reason, updated_at)\n VALUES (gen_random_uuid(), t, statement_timestamp(), p_person, p_project, p_kind, p_target, true, p_reason, statement_timestamp())\n ON CONFLICT (tenant_id, principal_id, target_kind, target_id) DO NOTHING;\n RETURN true;\nEND $$", ('pdos_next_app',)),
    ('notify_deactivated_handover(uuid,uuid)', "CREATE FUNCTION public.notify_deactivated_handover(t uuid, person uuid) RETURNS integer\n LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\nDECLARE p projects; cards integer := 0; counts jsonb;\nBEGIN\n IF t IS DISTINCT FROM nullif(current_setting('pdos.tenant_id',true),'')::uuid OR NOT EXISTS(SELECT 1 FROM tenant_administrators a JOIN principals x\n   ON x.tenant_id=a.tenant_id AND x.id=a.principal_id WHERE a.tenant_id=t AND a.principal_id=scope_actor()\n   AND a.active AND x.active AND x.kind='human') OR scope_actor() IS DISTINCT FROM scope_requester() THEN\n  RAISE EXCEPTION 'Only an administrator stops an account' USING ERRCODE='23514'; END IF;\n FOR p IN SELECT DISTINCT pr.* FROM projects pr JOIN project_members m ON m.tenant_id=pr.tenant_id AND m.project_id=pr.id\n   WHERE pr.tenant_id=t AND m.principal_id=person AND (m.left_at IS NULL OR m.handover_pending) AND pr.owner_id<>person LOOP\n  SELECT jsonb_build_object('person_id', person,\n    'tasks', count(*) FILTER (WHERE kind='work_task'),\n    'commitments', count(*) FILTER (WHERE kind='work_commitment'),\n    'external_waits', count(*) FILTER (WHERE kind='external_wait'),\n    'source', 'account_deactivated')\n   INTO counts FROM project_handover_items_of(t, p.id, person);\n  CONTINUE WHEN (counts->>'tasks')::int + (counts->>'commitments')::int + (counts->>'external_waits')::int = 0;\n  IF notification_emit(t, p.owner_id, 'decide', 'member.deactivated', true, p.id, 'member_handover', person, NULL, counts, 600) IS NOT NULL THEN\n   cards := cards + 1; END IF;\n END LOOP;\n RETURN cards;\nEND $$", ('pdos_next_app',)),
)

